#include <vector>
#include <unordered_map>

class Solution {
    long long countTriplets(const std::vector<int>& a, const std::vector<int>& b) {
        std::unordered_map<long long, int> prodCounts;
        int m = b.size();
        for (int j = 0; j < m; ++j) {
            for (int k = j + 1; k < m; ++k) {
                prodCounts[(long long)b[j] * b[k]]++;
            }
        }
        long long ans = 0;
        for (int x : a) {
            long long sq = (long long)x * x;
            if (prodCounts.count(sq)) ans += prodCounts[sq];
        }
        return ans;
    }
public:
    int numTriplets(std::vector<int>& nums1, std::vector<int>& nums2) {
        return countTriplets(nums1, nums2) + countTriplets(nums2, nums1);
    }
};

import java.util.*;

class Solution {
    private long countTriplets(int[] a, int[] b) {
        Map<Long, Integer> prodCounts = new HashMap<>();
        int m = b.length;
        for (int j = 0; j < m; j++) {
            for (int k = j + 1; k < m; k++) {
                long prod = (long) b[j] * b[k];
                prodCounts.put(prod, prodCounts.getOrDefault(prod, 0) + 1);
            }
        }
        long ans = 0;
        for (int x : a) {
            long sq = (long) x * x;
            ans += prodCounts.getOrDefault(sq, 0);
        }
        return ans;
    }
    public int numTriplets(int[] nums1, int[] nums2) {
        return (int)(countTriplets(nums1, nums2) + countTriplets(nums2, nums1));
    }
}

